class Solution:
    def numberOfWays(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            for j in range(i + 1, n):
                if s[j] == s[i]:
                    continue
                for k in range(j + 1, n):
                    if s[k] != s[j]:
                        ans += 1
        return ans

