class Solution:
    def numberOfWays(self, s: str) -> int:
        n = len(s)
        left = [0] * n
        right = [0] * n
        z = o = 0
        for i, ch in enumerate(s):
            left[i] = o if ch == '0' else z
            if ch == '0':
                z += 1
            else:
                o += 1
        z = o = 0
        for i in range(n - 1, -1, -1):
            right[i] = o if s[i] == '0' else z
            if s[i] == '0':
                z += 1
            else:
                o += 1
        return sum(left[i] * right[i] for i in range(n))

