class Solution {
public:
    long long numberOfWays(string s) {
        int n = s.size();
        vector<long long> left(n), right(n);
        long long z = 0, o = 0;
        for (int i = 0; i < n; i++) {
            left[i] = (s[i] == '0') ? o : z;
            if (s[i] == '0') z++; else o++;
        }
        z = 0; o = 0;
        for (int i = n - 1; i >= 0; i--) {
            right[i] = (s[i] == '0') ? o : z;
            if (s[i] == '0') z++; else o++;
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans += left[i] * right[i];
        return ans;
    }
};

